SELECT
a.homepage_id, a.book_package_bundle_idx, a.book_package_bundle_title, b.book_package_name, b.author, b.publisher, b.publish_year, a.loan_count, a.quantity, a.grade, b.category, b.keyword, b.desc_link, b.image_link, REGEXP_REPLACE(b.content, '<[^>]*>', '') AS content, b.org_file_name, b.server_file_name, b.file_extension, b.file_size, b.doc_org_file_name, b.doc_server_file_name, b.doc_file_extension, b.doc_file_size, b.book_package_bundle_detail_idx, c.bundle_idx
FROM BOOK_PACKAGE_BUNDLE a, BUNDLE_LIST b, BOOK_PACKAGE_BUNDLE_DETAIL c WHERE a.homepage_id = #{homepage_id} AND a.book_package_bundle_idx = c.book_package_bundle_idx AND b.book_package_bundle_detail_idx = c.book_package_bundle_detail_idx AND a.book_package_bundle_idx = #{book_package_bundle_idx}

${pagingTop} SELECT a.homepage_id, a.book_package_bundle_idx, a.book_package_bundle_title, a.loan_count, a.quantity, a.grade, c.bundle_idx, LISTAGG(b.book_package_name,',') WITHIN GROUP (ORDER BY b.book_package_bundle_detail_idx ) AS book_package_name, LISTAGG(b.category,',') WITHIN GROUP (ORDER BY b.book_package_bundle_detail_idx ) AS category, LISTAGG(b.keyword,',') WITHIN GROUP (ORDER BY b.book_package_bundle_detail_idx ) AS keyword, TO_CHAR(d.loan_start_date, 'yyyy-MM-dd') AS loan_start_date, TO_CHAR(d.loan_end_date, 'yyyy-MM-dd') AS loan_end_date, NVL(d.lender_count, 0) AS lender_count FROM BOOK_PACKAGE_BUNDLE a, BUNDLE_LIST b, BOOK_PACKAGE_BUNDLE_DETAIL c, ( SELECT book_package_bundle_idx, COUNT(request_status) AS lender_count, MAX(loan_start_date) AS loan_start_date, MAX(loan_end_date) AS loan_end_date FROM BOOK_PACKAGE_BUNDLE_LOAN WHERE request_status IN (0, 1, 2) GROUP BY book_package_bundle_idx ) d WHERE a.homepage_id = #{homepage_id} AND a.book_package_bundle_idx = c.book_package_bundle_idx AND b.book_package_bundle_detail_idx = c.book_package_bundle_detail_idx AND a.book_package_bundle_idx = d.book_package_bundle_idx(+)
AND ${search_type} LIKE '%'||#{search_text}||'%'
AND REGEXP_LIKE(category, REPLACE(#{category}, ',', '|'))
AND grade = #{grade}
AND #{lender_count}
= <=
(SELECT COUNT(*) FROM BOOK_PACKAGE_BUNDLE_LOAN WHERE book_package_bundle_idx = a.book_package_bundle_idx AND request_status IN (0, 1, 2))
GROUP BY c.book_package_bundle_idx, a.homepage_id, a.book_package_bundle_idx, a.book_package_bundle_title, a.loan_count, a.quantity, a.grade, d.loan_start_date, d.loan_end_date, c.bundle_idx, d.lender_count ORDER BY book_package_bundle_idx DESC ${pagingBottom}

