AND	${search_type} LIKE '%'||#{search_text}||'%'



	AND	return_yn = #{return_yn}
	AND	request_status = '2'


	AND	request_status = #{request_status}



AND	TO_CHAR(loan_start_date, 'yyyy') = #{loan_start_date}


AND b.add_id = #{add_id}

${pagingTop} SELECT b.book_package_bundle_idx, b.book_package_bundle_loan_idx, a.book_package_bundle_title, b.request_name, b.school_name, a.quantity, a.loan_count, TO_CHAR(b.loan_start_date, 'yyyy-MM-dd') AS loan_start_date, TO_CHAR(b.loan_end_date, 'yyyy-MM-dd') AS loan_end_date, b.phone, b.school_tel, b.request_content, b.request_status, b.return_yn, b.add_id, b.add_date, LISTAGG(c.category,',') WITHIN GROUP (ORDER BY c.book_package_bundle_detail_idx ) AS category FROM BOOK_PACKAGE_BUNDLE a, BOOK_PACKAGE_BUNDLE_LOAN b, BUNDLE_LIST c WHERE a.book_package_bundle_idx = b.book_package_bundle_idx
AND ${search_type} LIKE '%'||#{search_text}||'%'
AND return_yn = #{return_yn} AND request_status = '2'
AND request_status = #{request_status}
AND TO_CHAR(loan_start_date, 'yyyy') = #{loan_start_date}
AND REGEXP_LIKE(category, REPLACE(#{category}, ',', '|'))
AND b.add_id = #{add_id}
GROUP BY b.book_package_bundle_idx, b.book_package_bundle_loan_idx, a.book_package_bundle_title, b.request_name, b.school_name, a.quantity, a.loan_count, b.loan_start_date, b.loan_end_date, b.phone, b.school_tel, b.request_content, b.request_status, b.return_yn, b.add_id, b.add_date ORDER BY b.book_package_bundle_loan_idx DESC ${pagingBottom}

